begin;
do $$ declare uid uuid;eng uuid;buyer uuid;cid uuid;pid uuid;cat public.input_catalog;setting jsonb;v bigint;payload jsonb;b0 uuid;b1 uuid;b2 uuid;b3 uuid;old_config jsonb;begin
 select id,company_id into uid,cid from public.profiles where role='MASTER' and active limit 1;
 select id into eng from public.profiles where role='ENGINEERING' and company_id=cid and active limit 1;
 select id into buyer from public.profiles where role='PURCHASING' and company_id=cid and active limit 1;
 perform set_config('request.jwt.claim.sub',uid::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 insert into public.projects(company_id,name,code,created_by) values(cid,'BDI TEST ROLLBACK','BDI-'||left(gen_random_uuid()::text,8),uid) returning id into pid;
 select * into cat from public.input_catalog where input_type='MATERIAL' and catalog_active limit 1;
 payload:=jsonb_build_object('title','BDI versão','baseDate','2026-11-07','items',jsonb_build_array(jsonb_build_object('inputId',cat.id,'source','shared','code',cat.catalog_code,'unit',cat.unit,'quantity',10,'unitPrice',10)));
 execute 'set local role authenticated';
 setting:=public.get_company_bdi();v:=(setting->>'version')::bigint;
 setting:=public.save_company_bdi('{"enabled":false,"mode":"PERCENT","rate":20}',v);v:=(setting->>'version')::bigint;
 b0:=public.save_budget_version(pid,payload);
 if not exists(select 1 from public.budgets where id=b0 and total=100 and bdi_percent=0 and bdi_amount=0 and bdi_config->>'enabled'='false') then raise exception 'Disabled BDI charged';end if;
 setting:=public.save_company_bdi('{"enabled":true,"mode":"PERCENT","rate":20}',v);v:=(setting->>'version')::bigint;
 b1:=public.save_budget_version(pid,payload);
 select bdi_config into old_config from public.budgets where id=b1;
 if not exists(select 1 from public.budgets where id=b1 and total=120 and bdi_config->>'mode'='PERCENT') then raise exception 'Company default not applied';end if;
 begin perform public.save_company_bdi('{"enabled":true,"mode":"PERCENT","rate":50}',v-1);raise exception 'ASSERT stale settings';exception when others then if sqlerrm='ASSERT stale settings' then raise;end if;end;
 setting:=public.save_company_bdi('{"enabled":true,"mode":"PERCENT","rate":30}',v);v:=(setting->>'version')::bigint;
 if not exists(select 1 from public.budgets where id=b1 and total=120 and bdi_config=old_config) then raise exception 'Historical budget changed';end if;
 b2:=public.save_budget_version(pid,payload||jsonb_build_object('revisionOf',b1,'revisionReason','Revisão preserva a configuração','bdiConfig',old_config));
 if not exists(select 1 from public.budgets where id=b2 and total=120 and bdi_percent=20 and revision_of=b1) then raise exception 'Revision adopted a new company default';end if;
 b3:=public.save_budget_version(pid,payload||jsonb_build_object('bdiConfig','{"ac":20,"sg":0,"r":0,"df":0,"l":0,"cp":0,"issBase":0,"issRate":0}'::jsonb));
 if not exists(select 1 from public.budgets where id=b3 and total=120 and bdi_config->>'mode'='COMPONENTS') then raise exception 'Legacy component calculation changed';end if;
 begin perform public.save_budget_version(pid,payload||jsonb_build_object('bdiConfig','{"enabled":true,"mode":"PERCENT","rate":-1}'::jsonb));raise exception 'ASSERT negative rate';exception when others then if sqlerrm='ASSERT negative rate' then raise;end if;end;
 begin update public.company_bdi_settings set config='{}' where company_id=cid;raise exception 'ASSERT direct setting update';exception when others then if sqlerrm='ASSERT direct setting update' then raise;end if;end;
 execute 'reset role';
 if not exists(select 1 from public.operation_audit where entity_id=cid and action='COMPANY_BDI') then raise exception 'Default not audited';end if;
 perform set_config('request.jwt.claim.sub',buyer::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.get_company_bdi();raise exception 'ASSERT Purchasing reads default';exception when others then if sqlerrm='ASSERT Purchasing reads default' then raise;end if;end;
 begin perform public.save_company_bdi('{"enabled":false}',v);raise exception 'ASSERT Purchasing edits default';exception when others then if sqlerrm='ASSERT Purchasing edits default' then raise;end if;end;
 if exists(select 1 from public.company_bdi_settings where company_id=cid) then raise exception 'Setting RLS leak';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',eng::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',eng,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 setting:=public.get_company_bdi();
 if (setting->>'version')::bigint<>v then raise exception 'Engineering default missing';end if;
 execute 'reset role';
end $$;
rollback;
